//! Original Tape live profile. Accepted captured Tape and Native defaults unchanged.
mod resources;mod shaper;mod tone;mod delay;mod timeline;mod oscillator;
#[cfg(feature="allocation-audit")]mod allocation;
use resources::{Curves,CHUNK};use timeline::LiveTimeline;
const Q:usize=128;const CAPACITY:usize=256;const FRAME_MAX:f64=1099511627648.;
const INTRINSIC:[f64;10]=[1.,1.,440.,440.,1.,1.,350.,440.,440.,0.];
const FREQUENCIES:[usize;4]=[2,3,7,8];const DEPTHS:[usize;4]=[0,1,4,5];
#[derive(Clone,Copy)]struct Command{kind:u8,lane:usize,value:f64,slot:usize,generation:u32,frame:f64,seconds:f64}
const EMPTY:Command=Command{kind:0,lane:0,value:0.,slot:0,generation:0,frame:0.,seconds:0.};
pub struct Engine{rate:f64,ready:bool,frame:u64,origin:u64,construct:[(f64,f64);16],construct_count:usize,last_authored:f64,lanes:[LiveTimeline;10],targets:[f64;10],sines:[oscillator::Sine;4],started:[bool;4],starts:[f64;4],lfos:[[f32;Q];4],curves:Curves,scratch:[f32;CHUNK],queue:[Command;32],queued:usize,applied:u64,rejected:u64,shaper:shaper::Shaper,tone:tone::Lowpass,delay:delay::Delay,input:[[f32;Q];2],output:[[f32;Q];2],stages:[[[f32;Q];2];2],calls:u64,processed:[u64;11],peak:f64,last_delay:f32}
fn canonical(f:f64)->bool{f.is_finite()&&f>=0.&&f<=FRAME_MAX&&f.fract()==0.&&f%128.==0.}
fn timestamp(f:f64,s:f64,r:f64)->bool{canonical(f)&&s.is_finite()&&s==f/r}
fn index(v:f64,max:usize)->Option<usize>{if v.is_finite()&&v>=0.&&v.fract()==0.&&v<=max as f64{Some(v as usize)}else{None}}
fn generation(v:f64)->Option<u32>{if v.is_finite()&&v>=1.&&v<=u32::MAX as f64&&v.fract()==0.{Some(v as u32)}else{None}}
fn valid_lane(i:usize,v:f64)->bool{v.is_finite()&&v==v as f32 as f64&&match i{0=>(0. ..=0.003f32 as f64).contains(&v),1=>(0. ..=0.0015f32 as f64).contains(&v),2=>(0.05f32 as f64..=5.).contains(&v),3=>((0.05f64*0.37)as f32 as f64..=(5f64*0.37)as f32 as f64).contains(&v),4=>(0. ..=0.00025f32 as f64).contains(&v),5=>(0. ..=0.00012f32 as f64).contains(&v),6=>(500. ..=20000.).contains(&v),7=>v==7.3f32 as f64,8=>v==11.7f32 as f64,9=>v==0.006f32 as f64,_=>false}}
impl Engine{
 pub fn new(rate:f64)->Option<Box<Self>>{if !rate.is_finite()||rate.fract()!=0.||!(8000. ..=192000.).contains(&rate){return None;}Some(Box::new(Self{rate,ready:false,frame:0,origin:0,construct:[(0.,0.);16],construct_count:0,last_authored:-1.,lanes:std::array::from_fn(|i|LiveTimeline::new(INTRINSIC[i],CAPACITY,rate)),targets:INTRINSIC,sines:std::array::from_fn(|_|oscillator::Sine::new(rate,0.)),started:[false;4],starts:[0.;4],lfos:[[0.;Q];4],curves:Curves::new(),scratch:[0.;CHUNK],queue:[EMPTY;32],queued:0,applied:0,rejected:0,shaper:shaper::Shaper::new(),tone:tone::Lowpass::new(rate),delay:delay::Delay::new(rate),input:[[0.;Q];2],output:[[0.;Q];2],stages:[[[0.;Q];2];2],calls:0,processed:[0;11],peak:0.,last_delay:0.006}))}
 fn reject(&mut self)->bool{self.rejected+=1;false}
 pub fn constructor(&mut self,slot:usize,frame:f64,seconds:f64)->bool{if self.ready||slot>=16||slot!=self.construct_count||!timestamp(frame,seconds,self.rate)||slot>0&&frame<self.construct[slot-1].0{return self.reject();}self.construct[slot]=(frame,seconds);self.construct_count+=1;true}
 pub fn prepare(&mut self,frame:f64,seconds:f64,slot:usize,g:u32)->bool{if self.ready||self.construct_count!=16||!timestamp(frame,seconds,self.rate)||frame>self.construct[0].0||!self.curves.ready(slot,g){return self.reject();}for(slot,lane,value)in[(1,9,0.006),(2,2,0.6),(3,0,0.),(5,3,0.6*0.37),(6,1,0.),(8,7,7.3),(9,4,0.),(11,8,11.7),(12,5,0.)]{let v=value as f32 as f64;self.lanes[lane].intrinsic(v);assert!(self.lanes[lane].add_seconds(self.construct[slot].1,0,v,0.));self.targets[lane]=v;}assert!(self.lanes[6].add_seconds(self.construct[15].1,2,9000.,0.03));self.targets[6]=9000.;self.starts=[self.construct[4].1,self.construct[7].1,self.construct[10].1,self.construct[13].1];assert!(self.curves.activate(slot,g));self.frame=frame as u64;self.origin=self.frame;self.last_authored=self.construct[15].0;self.ready=true;true}
 pub fn sync(&mut self,frame:f64)->bool{if !self.ready||!canonical(frame)||frame<self.frame as f64{return self.reject();}self.frame=frame as u64;true}
 fn command_ok(&self,frame:f64,seconds:f64)->bool{self.ready&&self.queued<32&&timestamp(frame,seconds,self.rate)&&frame>=self.last_authored&&frame<=self.frame as f64}
 pub fn enqueue_lane(&mut self,lane:usize,value:f64,frame:f64,seconds:f64)->bool{if !valid_lane(lane,value)||!self.command_ok(frame,seconds){return self.reject();}self.queue[self.queued]=Command{kind:0,lane,value,frame,seconds,..EMPTY};self.queued+=1;self.last_authored=frame;true}
 pub fn enqueue_curve(&mut self,slot:usize,g:u32,frame:f64,seconds:f64)->bool{if !self.command_ok(frame,seconds)||!self.curves.reference(slot,g){return self.reject();}self.queue[self.queued]=Command{kind:1,slot,generation:g,frame,seconds,..EMPTY};self.queued+=1;self.last_authored=frame;true}
 pub fn commit(&mut self)->bool{let mut needed=[0usize;10];for c in &self.queue[..self.queued]{if c.kind==1&&!self.curves.ready(c.slot,c.generation){return false;}if c.kind==0{needed[c.lane]+=1;}}for(i,n)in needed.iter().enumerate(){if !self.lanes[i].available_at(*n,self.frame as f64){return self.reject();}}for i in 0..self.queued{let c=self.queue[i];if c.kind==0{self.lanes[c.lane].prune_for_insert(self.frame as f64);assert!(self.lanes[c.lane].add_seconds(c.seconds,2,c.value,0.03));self.targets[c.lane]=c.value;}else{assert!(self.curves.activate(c.slot,c.generation));self.curves.unreference(c.slot);}self.applied+=1;}self.queued=0;true}
 fn oscillator_block(&mut self,which:usize,constant:bool){let lane=FREQUENCIES[which];let sine=&mut self.sines[which];let mut offset=0;if !self.started[which]{let start=self.starts[which]*self.rate;let ceil=((start*1024.).round()/1024.).ceil()as u64;offset=ceil.saturating_sub(self.frame).min(Q as u64)as usize;if offset==Q{self.lfos[which].fill(0.);return;}let fraction=start-ceil as f64;if fraction>0.{offset+=1;}sine.scheduling_offset(fraction,self.lanes[lane].output[0],constant);self.started[which]=true;}let n=Q-offset;let start=sine.virtual_index();self.lfos[which][..offset].fill(0.);for i in 0..n{self.lfos[which][offset+i]=sine.tick(self.lanes[lane].output[i],self.frame+i as u64,constant,!constant&&i<n/4*4);}if constant&&n!=Q{sine.finish_partial_constant(start,n,self.lanes[lane].output[0]);}}
 pub fn render(&mut self,channels:usize,activity:u32)->bool{if !self.ready||self.queued!=0||self.frame+128>FRAME_MAX as u64||channels>2||activity>=1<<22{return self.reject();}let modes:[usize;11]=std::array::from_fn(|i|((activity>>(i*2))&3)as usize);if modes.iter().any(|m|*m>2)||modes.iter().any(|m|*m!=0)&&self.frame<self.construct[15].0 as u64||modes[0]==2&&(0..channels).any(|c|self.input[c].iter().any(|v|!v.is_finite())){return self.reject();}let constants=FREQUENCIES.map(|i|!self.lanes[i].accurate(self.frame));for i in 0..4{if modes[3+i]!=0{self.lanes[FREQUENCIES[i]].prepare(self.frame,self.rate);}if modes[7+i]!=0{self.lanes[DEPTHS[i]].prepare(self.frame,self.rate);}if modes[3+i]==2{self.oscillator_block(i,constants[i]);}else{self.lfos[i].fill(0.);}}if modes[1]!=0{self.lanes[6].prepare(self.frame,self.rate);self.lanes[6].clip_output(0.,(self.rate*0.5)as f32);}if modes[2]!=0{self.lanes[9].prepare(self.frame,self.rate);}self.calls+=1;self.peak=0.;self.output.fill([0.;Q]);self.stages.fill([[0.;Q];2]);let active=self.curves.active.unwrap();for i in 0..Q{let shaped=if modes[0]==2{self.shaper.tick(if channels==0{[0.;2]}else{[self.input[0][i],self.input[channels-1][i]]},&self.curves.slots[active].data)}else{[0.;2]};let toned=if modes[1]==2{self.tone.tick(shaped,self.lanes[6].output[i],self.frame+i as u64)}else{[0.;2]};if modes[2]==2{let mut seconds=self.lanes[9].output[i];for j in 0..4{if modes[7+j]==2{seconds+=self.lfos[j][i]*self.lanes[DEPTHS[j]].output[i];}}self.last_delay=seconds;let out=self.delay.tick(toned,seconds);for ch in 0..2{self.output[ch][i]=out[ch];self.peak=self.peak.max(out[ch].abs()as f64);}}for ch in 0..2{self.stages[0][ch][i]=shaped[ch];self.stages[1][ch][i]=toned[ch];}}for i in 0..11{if modes[i]==2{self.processed[i]+=128;}}self.frame+=128;true}
}
#[no_mangle]pub extern "C" fn tape_live_api()->u32{1}
#[no_mangle]pub extern "C" fn tape_live_new(rate:f64)->*mut Engine{Engine::new(rate).map(Box::into_raw).unwrap_or(std::ptr::null_mut())}
#[no_mangle]pub unsafe extern "C" fn tape_live_free(p:*mut Engine){if !p.is_null(){drop(Box::from_raw(p));}}
#[no_mangle]pub extern "C" fn tape_live_constructor(p:&mut Engine,slot:f64,frame:f64,seconds:f64)->u32{index(slot,15).is_some_and(|i|p.constructor(i,frame,seconds))as u32}
#[no_mangle]pub extern "C" fn tape_live_prepare(p:&mut Engine,frame:f64,seconds:f64,slot:f64,g:f64)->u32{let(Some(s),Some(g))=(index(slot,31),generation(g))else{return 0;};p.prepare(frame,seconds,s,g)as u32}
#[no_mangle]pub extern "C" fn tape_live_sync(p:&mut Engine,frame:f64)->u32{p.sync(frame)as u32}
#[no_mangle]pub extern "C" fn tape_live_lane(p:&mut Engine,lane:f64,value:f64,frame:f64,seconds:f64)->u32{index(lane,9).is_some_and(|i|p.enqueue_lane(i,value,frame,seconds))as u32}
#[no_mangle]pub extern "C" fn tape_live_curve(p:&mut Engine,slot:f64,g:f64,frame:f64,seconds:f64)->u32{let(Some(s),Some(g))=(index(slot,31),generation(g))else{return 0;};p.enqueue_curve(s,g,frame,seconds)as u32}
#[no_mangle]pub extern "C" fn tape_live_commit(p:&mut Engine)->u32{p.commit()as u32}
#[no_mangle]pub extern "C" fn tape_live_render(p:&mut Engine,channels:f64,activity:f64)->u32{let(Some(c),Some(a))=(index(channels,2),index(activity,(1<<22)-1))else{return 0;};p.render(c,a as u32)as u32}
#[no_mangle]pub extern "C" fn tape_live_reserve(p:&mut Engine,slot:f64,g:f64,drive:f64)->u32{let(Some(s),Some(g))=(index(slot,31),generation(g))else{return 0;};p.curves.reserve(s,g,drive)as u32}
#[no_mangle]pub extern "C" fn tape_live_service(p:&mut Engine,ordinal:f64)->u32{index(ordinal,u32::MAX as usize).is_some_and(|i|p.curves.begin_service(i as u64))as u32}
#[no_mangle]pub extern "C" fn tape_live_scratch(p:&mut Engine)->*mut f32{p.scratch.as_mut_ptr()}
#[no_mangle]pub extern "C" fn tape_live_upload(p:&mut Engine,slot:f64,g:f64,offset:f64,n:f64)->u32{let(Some(s),Some(g),Some(o),Some(n))=(index(slot,31),generation(g),index(offset,2049),index(n,1024))else{return 0;};p.curves.upload(s,g,o,&p.scratch[..n])as u32}
#[no_mangle]pub extern "C" fn tape_live_seal(p:&mut Engine,slot:f64,g:f64)->u32{let(Some(s),Some(g))=(index(slot,31),generation(g))else{return 0;};p.curves.seal(s,g)as u32}
#[no_mangle]pub extern "C" fn tape_live_release_curve(p:&mut Engine,slot:f64,g:f64)->u32{let(Some(s),Some(g))=(index(slot,31),generation(g))else{return 0;};p.curves.release(s,g)as u32}
#[no_mangle]pub extern "C" fn tape_live_input(p:&mut Engine,ch:f64)->*mut f32{index(ch,1).map_or(std::ptr::null_mut(),|c|p.input[c].as_mut_ptr())}
#[no_mangle]pub extern "C" fn tape_live_output(p:&Engine,ch:f64)->*const f32{index(ch,1).map_or(std::ptr::null(),|c|p.output[c].as_ptr())}
#[no_mangle]pub extern "C" fn tape_live_stage(p:&Engine,stage:f64,ch:f64)->*const f32{let(Some(s),Some(c))=(index(stage,1),index(ch,1))else{return std::ptr::null();};p.stages[s][c].as_ptr()}
#[no_mangle]pub extern "C" fn tape_live_lane_value(p:&Engine,lane:f64,sample:f64)->f64{let(Some(l),Some(i))=(index(lane,9),index(sample,127))else{return f64::NAN;};p.lanes[l].output[i]as f64}
#[no_mangle]pub extern "C" fn tape_live_target(p:&Engine,lane:f64)->f64{index(lane,9).map_or(f64::NAN,|i|p.targets[i])}
#[no_mangle]pub extern "C" fn tape_live_curve_stat(p:&Engine,slot:f64,key:f64)->f64{let(Some(s),Some(k))=(index(slot,31),index(key,4))else{return f64::NAN;};let c=&p.curves.slots[s];match k{0=>c.state as f64,1=>c.generation as f64,2=>c.written as f64,3=>c.references as f64,4=>c.drive,_=>f64::NAN}}
#[no_mangle]pub extern "C" fn tape_live_stat(p:&Engine,key:f64)->f64{let Some(k)=index(key,29)else{return f64::NAN;};match k{0=>p.frame as f64,1=>p.peak,2=>p.calls as f64,3=>p.queued as f64,4=>p.applied as f64,5=>p.rejected as f64,6=>p.curves.active.map_or(-1.,|s|s as f64),7=>p.curves.copied as f64,8=>p.curves.max_copied as f64,9=>p.curves.total_copied as f64,10=>p.curves.service as f64,11=>p.ready as u32 as f64,12=>p.last_delay as f64,13=>p.origin as f64,14..=17=>p.sines[k-14].phase(),18..=28=>p.processed[k-18]as f64,29=>128.,_=>f64::NAN}}
